// ── Daten aus vorherigen Nodes holen ──────────────────────────────────────
const rev         = $('GET REVENUE1').first().json;
const cnt         = $('GET ORDERS COUNT1').first().json;
const orderDetails = $('GET ORDER DETAILS').all();

const umsatzB2C   = rev.Umsatz_B2C   ?? '0.00';
const umsatzB2B   = rev.Umsatz_B2B   ?? '0.00';
const anzahlB2C   = cnt.Bestellungen_B2C  ?? 0;
const anzahlB2B   = cnt.Bestellungen_B2B   ?? 0;

// ── Produkttabelle aufbauen ────────────────────────────────────────────────
let tableRows = '';
for (const item of orderDetails) {
  const d = item.json;
  // Zeile nur rendern wenn Werte > 0 vorhanden
  const hasB2C = (d.Menge_B2C > 0 || d.Umsatz_B2C > 0);
  const hasB2B = (d.Menge_B2B > 0 || d.Umsatz_B2B > 0);
  if (!hasB2C && !hasB2B) continue;

  tableRows += `
  <tr bgcolor="#ffffff">
    <td>${d.Artikelnummer}</td>
    <td>${d.Artikelname}</td>
    <td style="text-align:right;">${hasB2C ? d.Menge_B2C : '-'}</td>
    <td style="text-align:right;">${hasB2C ? d.Umsatz_B2C + '&euro;' : '-'}</td>
    <td style="text-align:right;">${hasB2B ? d.Menge_B2B : '-'}</td>
    <td style="text-align:right;">${hasB2B ? d.Umsatz_B2B + '&euro;' : '-'}</td>
  </tr>`;
}

const productTable = `
<table cellspacing="0" cellpadding="5" border="1"
       style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:12px;">
  <tr bgcolor="#1a1a1a" style="color:white;">
    <td colspan="2"></td>
    <td colspan="2" style="text-align:center;background:#fac3c6;color:black;"><b>B2C</b></td>
    <td colspan="2" style="text-align:center;text-color:white;background:#000000;"><b>B2B</b></td>
  </tr>
  <tr bgcolor="#333333" style="color:white;">
    <td><b>Artikelnummer</b></td>
    <td><b>Artikelname</b></td>
    <td style="background:#fac3c6;color:black;"><b>Menge</b></td>
    <td style="background:#fac3c6;color:black;"><b>Umsatz</b></td>
    <td style="text-color:white;background:#000000;"><b>Menge</b></td>
    <td style="text-color:white;background:#000000;"><b>Umsatz</b></td>
  </tr>
  ${tableRows}
</table>`;

// ── Datumsformatierung (de-DE) ─────────────────────────────────────────────
